const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v)),mean=a=>a.reduce((x,y)=>x+y,0)/Math.max(1,a.length),variance=a=>{let m=mean(a);return mean(a.map(v=>(v-m)**2))};
let state={A:50,B:50,rA:50,rB:50,room:'',connected:{A:false,B:false},inputSource:'smartphones',input:{A:{method:'slider',direction:'vertical'},B:{method:'slider',direction:'vertical'}},inputType:{A:'slider',B:'slider'},running:false,start:0,score:0,combo:0,data:[],history:[],last:0,settings:{target:100,tol:5,duration:20,task:'sum'}};
class PeerBus{constructor(room,role='host'){this.room=room;this.role=role;this.connections={};this.peer=new Peer();this.peer.on('error',e=>this.onError?.(e));role==='host'?(this.peer.on('open',id=>{this.room=id;this.onReady?.(id)}),this.peer.on('connection',c=>this.accept(c))):this.peer.on('open',()=>this.connect())}connect(){this.connection=this.peer.connect(this.room,{reliable:false,metadata:{role:this.role,sessionId:crypto.randomUUID()}});this.connection.on('open',()=>this.onConnected?.());this.connection.on('data',m=>{if(m.type==='feedback')this.onFeedback?.(m.payload);if(m.type==='input-config')this.onConfig?.(m.config)});this.connection.on('close',()=>this.onClose?.())}accept(c){let r=c.metadata?.role;if(!['A','B'].includes(r))return c.close();this.connections[r]?.close();this.connections[r]=c;c.on('open',()=>{state.connected[r]=true;c.send({type:'input-config',config:state.input[r]})});c.on('data',m=>{if(m.type!=='input')return;if(state.inputSource==='smartphones'){state[r]=clamp(+m.normalizedValue);state['r'+r]=+m.rawValue;state.inputType[r]=m.inputType}state.connected[r]=true});c.on('close',()=>{if(this.connections[r]===c){delete this.connections[r];state.connected[r]=false}})}send(m,r){if(this.role==='host'){r?this.connections[r]?.open&&this.connections[r].send(m):Object.values(this.connections).forEach(c=>c.open&&c.send(m))}else this.connection?.open&&this.connection.send(m)}close(){Object.values(this.connections).forEach(c=>c.close());this.connection?.close();this.peer.destroy()}}
let bus,demo;
function task(){return state.task==='difference'?state.A-state.B:state.A+state.B}function setInput(r,u){state.input[r]={...state.input[r],...u};bus?.send({type:'input-config',config:state.input[r]},r);host()}
function link(r){let u=new URL(location.href);u.search='';u.searchParams.set('room',state.room);u.searchParams.set('player',r);return u.href}function room(){let e=$('#room');if(!state.room){e.innerHTML='<button class="primary" id="roomBtn">Create room</button>';$('#roomBtn').onclick=()=>{bus?.close();bus=new PeerBus('');bus.onReady=id=>{state.room=id;room()};e.innerHTML='<p class="note">Creating room…</p>'};return}e.innerHTML=`<b>ROOM ${state.room.slice(-6).toUpperCase()}</b><div class="qr">${['A','B'].map(r=>`<div class="qrbox"><b>PLAYER ${r}</b><div id="qr${r}"></div><a href="${link(r)}">${link(r)}</a></div>`).join('')}</div>`;['A','B'].forEach(r=>new QRCode($('#qr'+r),{text:link(r),width:150,height:150}))}
function cfg(r){let c=state.input[r],tilt=c.method==='tilt';return `<fieldset class="player-input-config"><legend>Player ${r}</legend><label>Input Method<select data-m="${r}"><option value="slider" ${c.method==='slider'?'selected':''}>Slider</option><option value="tilt" ${tilt?'selected':''}>Tilt</option><option value="touch" ${c.method==='touch'?'selected':''}>Touch Area (Pressure-like)</option></select></label><label>${tilt?'Tilt direction':'Slider direction'}<select data-d="${r}"><option value="vertical" ${c.direction==='vertical'?'selected':''}>${tilt?'Left–Right':'Vertical'}</option><option value="horizontal" ${c.direction==='horizontal'?'selected':''}>${tilt?'Forward–Backward':'Horizontal'}</option></select></label></fieldset>`}
function host(){ $('#app').innerHTML=`<div class="head"><div class="eyebrow">COORDINATION LAB · UCM GAME</div><div class="status" id="gameState">SETUP</div></div><div class="grid"><section class="card setup"><h2>SETUP</h2><div class="tabs"><button class="active">INPUT</button></div><div class="controls"><label>Input source<select id="source"><option value="smartphones">Smartphone inputs</option><option value="demo">Demo inputs</option></select></label><label>Target<input id="target" type="number" value="${state.settings.target}"></label></div><div class="input-config-grid">${cfg('A')}${cfg('B')}</div><div id="room" class="room"></div></section><section class="card live" id="live"><h2>PLAY</h2><div class="players"><div class="player"><i class="dot" id="dotA"></i>Player A <span id="conA">Disconnected</span></div><div class="player"><i class="dot" id="dotB"></i>Player B <span id="conB">Disconnected</span></div></div><div class="numbers"><div class="num"><small>A</small><b id="a">50</b></div><div class="num"><small>B</small><b id="b">50</b></div><div class="num"><small>TASK / TARGET</small><b id="total">100 / 100</b></div></div><div class="gauge"><div class="targetline" id="tl"></div><div class="fill" id="fill"></div></div><p class="feedback" id="note">Create a room and connect both players.</p><div class="row"><button class="primary" id="start">Start trial</button><button id="demo">Demo inputs</button><span class="pill" id="score">Score 0 · Combo 0</span></div><div class="canvases"><canvas id="wave" class="plot"></canvas><canvas id="ucm" class="plot"></canvas></div></section><section class="card results"><h2>RESULT / UCM ANALYSIS</h2><div id="resultBody" class="note">Trial終了後に結果を表示します。</div></section></div>`;$('#source').value=state.inputSource;$('#source').onchange=e=>{state.inputSource=e.target.value;if(e.target.value==='demo')startDemo()};$('#target').oninput=e=>state.settings.target=+e.target.value;$$('[data-m]').forEach(e=>e.onchange=x=>setInput(x.target.dataset.m,{method:x.target.value,direction:'vertical'}));$$('[data-d]').forEach(e=>e.onchange=x=>setInput(x.target.dataset.d,{direction:x.target.value}));$('#start').onclick=start;$('#demo').onclick=()=>{state.inputSource='demo';$('#source').value='demo';startDemo()};room();requestAnimationFrame(tick)}
function startDemo(){state.connected={A:true,B:true};clearInterval(demo);let i=0;demo=setInterval(()=>{if(state.inputSource==='demo'){state.A=clamp(50+20*Math.sin(i/11));state.B=clamp(50-20*Math.sin(i++/11))}},80)}function start(){if(!state.connected.A||!state.connected.B)return $('#note').textContent='Connect both players or use Demo inputs.';state.running=true;state.start=performance.now();state.score=state.combo=0;state.data=[];$('#gameState').textContent='PLAY'}
function tick(t){if(!$('#live'))return;let T=task(),tar=state.settings.target,err=T-tar,ok=Math.abs(err)<=state.settings.tol;['A','B'].forEach(r=>{$('#dot'+r).classList.toggle('on',state.connected[r]);$('#con'+r).textContent=state.connected[r]?'Connected':'Disconnected'});$('#a').textContent=state.A.toFixed(0);$('#b').textContent=state.B.toFixed(0);$('#total').textContent=`${T.toFixed(1)} / ${tar}`;$('#fill').style.width=clamp(T/200*100)+'%';$('#tl').style.left=clamp(tar/200*100)+'%';if(!state.feedbackAt||t-state.feedbackAt>100){state.feedbackAt=t;bus?.send({type:'feedback',payload:{taskValue:T,target:tar,error:err,success:ok}})}if(state.running){if(ok){state.score++;state.combo++}else state.combo=0;if(t-state.last>80){state.last=t;state.data.push({timestamp:Date.now(),A:state.A,B:state.B,T,tar,err,success:ok,input_type_A:state.inputType.A,input_type_B:state.inputType.B});state.history.push({A:state.A,B:state.B,T});if(state.history.length>150)state.history.shift()}$('#score').textContent=`Score ${state.score} · Combo ${state.combo}`;$('#note').textContent=ok?'✓ TARGET ZONE':`Error ${err.toFixed(1)}`;if((t-state.start)/1000>=state.settings.duration){state.running=false;$('#gameState').textContent='RESULT';results()}}draw();requestAnimationFrame(tick)}
function draw(){let c=$('#wave');if(!c)return;for(let id of ['wave','ucm']){let q=$('#'+id),r=q.getBoundingClientRect(),d=devicePixelRatio;q.width=r.width*d;q.height=r.height*d;let x=q.getContext('2d');x.scale(d,d);x.fillStyle='#0b172b';x.fillRect(0,0,r.width,r.height);state.history.forEach((p,i)=>{x.fillStyle=i===state.history.length-1?'#fff':'#5eead4';x.beginPath();x.arc(p.A/100*r.width,r.height-p.B/100*r.height,2,0,7);x.fill()})}}
function results(){let d=state.data,u=d.map(x=>(x.A-x.B)/Math.sqrt(2)),o=d.map(x=>(x.A+x.B)/Math.sqrt(2)),vu=variance(u),vo=variance(o);$('#resultBody').innerHTML=`<div class="metric"><div><small>Score</small><b>${state.score}</b></div><div><small>V UCM / V ORT</small><b>${vu.toFixed(2)} / ${vo.toFixed(2)}</b></div></div>`}
function player(role,roomId){let config={method:'slider',direction:'vertical'},v=50,raw=50,n=0,pending=false,neutral=0,range=45,light,strong,attached=false,bus=new PeerBus(roomId,role);function send(){pending=false;bus.send({type:'input',playerId:role,inputType:config.method,rawValue:raw,normalizedValue:v,clientTimestamp:Date.now(),sequenceNumber:++n})}function put(x,r){v=clamp(x);raw=r;$('#value')&&( $('#value').textContent=v.toFixed(1),$('#bar').style.width=v+'%');if(!pending){pending=true;setTimeout(send,34)}}function render(){let input=config.method==='slider'?`<div class="slider-stage"><input id="slider" class="phone-slider ${config.direction}" type="range" min="0" max="100" step=".1" value="${v}"></div>`:config.method==='tilt'?`<button id="motion" class="primary">Enable Motion Sensor</button><div class="row"><button id="neutral">Neutral calibration</button><button id="range">Range calibration</button></div><p class="note">Raw: <b id="raw">${raw.toFixed(1)}</b>° · Range ±${range.toFixed(1)}°</p><p id="warn" class="note">Enable sensor then calibrate.</p>`:`<div id="pad" class="touch-area">Touch Area (Pressure-like)</div><div class="row"><button id="light">Light touch</button><button id="strong">Strong touch</button><button id="reset">Reset</button></div><p id="warn" class="note">Set Light and Strong touch.</p>`;$('#app').innerHTML=`<main class="player-shell"><div class="eyebrow">UCM CO-OP LAB</div><h1>PLAYER ${role}</h1><output id="value" class="player-value">${v.toFixed(1)}</output><section class="player-card input-screen">${input}</section><section class="player-card"><div id="remote">Connecting…</div><div class="feedback-row"><span>TOTAL</span><b id="sum">—</b><span>TARGET</span><b id="target">—</b></div><div class="player-meter"><i id="bar" style="width:${v}%"></i></div></section></main>`;if(config.method==='slider')$('#slider').oninput=e=>put(+e.target.value,+e.target.value);if(config.method==='tilt'){ $('#motion').onclick=motion;$('#neutral').onclick=()=>neutral=raw;$('#range').onclick=()=>range=Math.max(1,Math.abs(raw-neutral))}if(config.method==='touch'){let area=e=>{let a=(e.width||2*(e.radiusX||0))*(e.height||2*(e.radiusY||0));if(!a){$('#warn').textContent='Touch-area input is not reliably available on this device. Use Slider instead.';return}if(light!==undefined&&strong>light)put((a-light)/(strong-light)*100,a);else put(0,a)};$('#pad').onpointerdown=area;$('#pad').onpointermove=e=>e.buttons&&area(e);$('#light').onclick=()=>light=raw;$('#strong').onclick=()=>strong=raw;$('#reset').onclick=()=>{light=strong=undefined;$('#warn').textContent='Calibration reset.'}}}async function motion(){try{if(DeviceOrientationEvent.requestPermission&&await DeviceOrientationEvent.requestPermission()!=='granted')throw Error('Permission denied');if(!attached){addEventListener('deviceorientation',e=>{if(config.method==='tilt'){let z=config.direction==='vertical'?e.gamma:e.beta;if(z!=null){put(50+(z-neutral)/range*50,z);$('#raw')&&($('#raw').textContent=z.toFixed(1))}}});attached=true}$('#warn').textContent='Motion enabled.'}catch(e){$('#warn').textContent='Motion unavailable. Use Slider instead.'}}bus.onConnected=()=>{$('#remote').textContent='Connected';put(v,v)};bus.onConfig=c=>{config=c;render()};bus.onFeedback=p=>{$('#sum').textContent=p.taskValue?.toFixed(1);$('#target').textContent=p.target?.toFixed(1)};render()}
let p=new URLSearchParams(location.search);p.get('player')&&p.get('room')?player(p.get('player'),p.get('room')):host();
